const raw = $input.first().json;
if (raw.error) return [{json:{error:'Brief interpretation unavailable'}}];
const text = raw.text ?? raw.output;
try {
  if (typeof text !== 'string' || text.length > 12000) throw new Error('Invalid response');
  const clean = text.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
  const draft = JSON.parse(clean);
  if (!draft || Array.isArray(draft) || typeof draft !== 'object') throw new Error('Invalid draft');
  return [{json:draft}];
} catch { return [{json:{error:'Brief interpretation was invalid'}}]; }
